def mats(q):
 ts={'pelvis':np.eye(4)}
 for i,n in enumerate(J):
  axis=axes[i]/np.linalg.norm(axes[i]);rot=Rotation.from_rotvec(axis*q[i]).as_matrix();t=np.eye(4);t[:3,:3]=rot;t[:3,3]=cent[i]-rot@cent[i];ts[L[i+1]]=ts[P[i+1]]@t
 return ts
def pos(q,link,point):return (mats(q)[link]@np.r_[point,1])[:3]
def action_joints(q):
 out=np.zeros(69)
 for i,a in enumerate(A):
  name=a.replace('_A_','_');
  if name.endswith('J0'):
   out[J.index(name[:-1]+'1')]=q[i]/2;out[J.index(name[:-1]+'2')]=q[i]/2
